#!/usr/bin/env python3
"""Show reference output for a list of snippets: p.py file-with-snippets (separated by \n%%%\n)"""
import sys, os
sys.path.insert(0, "/tmp/mdB")
from ref import render_bodies

def show(snips, field="html", **kw):
    bodies = {}
    for i, s in enumerate(snips):
        bodies["c%03d" % i] = s
    out, p = render_bodies(bodies, field=field, **kw)
    if p.returncode != 0:
        sys.stderr.write("RC=%d\n%s\n%s\n" % (p.returncode, p.stdout[-3000:], p.stderr[-3000:]))
    for i, s in enumerate(snips):
        k = "c%03d" % i
        print("=" * 60)
        print("IN : " + repr(s))
        print("OUT: " + repr(out[k]))
    return out

if __name__ == "__main__":
    data = open(sys.argv[1], encoding="utf-8").read()
    snips = data.split("\n%%%\n")
    show(snips)
